import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from '../api_service';
import { 
  CheckCircle, 
  XCircle, 
  RefreshCw, 
  UserCheck, 
  Fingerprint,
  Volume2,
  VolumeX
} from 'lucide-react';

// Centralisation des logs pour la production
const logger = {
  info: (msg, data = "") => { if (process.env.NODE_ENV !== 'production') console.log(`[INFO] ${msg}`, data); },
  error: (msg, err = "") => console.error(`[ERROR] ${msg}`, err)
};

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  // Audio effects
  const playSound = (type) => {
    if (!soundEnabled) return;
    const audio = new Audio(type === 'success' ? '/sounds/success.mp3' : '/sounds/error.mp3');
    audio.play().catch(e => logger.error("Audio playback failed", e));
  };

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  // Cleanup webcam tracks
  useEffect(() => {
    return () => {
      if (webcamRef.current?.stream) {
        webcamRef.current.stream.getTracks().forEach(track => track.stop());
        logger.info("Webcam tracks stopped");
      }
    };
  }, []);

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setError(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Capture impossible");

      logger.info("Sending image for recognition...");
      const response = await attendanceAPI.recognize(imageSrc);
      const data = response.data;

      if (data.success) {
        playSound('success'); // 🔊 Son de succès
        setResult({
          name: data.student,
          email: data.email,
          confidence: data.confidence,
          timestamp: data.timestamp,
          message: data.message,
          attendanceId: data.attendance_id
        });
        logger.info("Recognition success", data.student);
      }
    } catch (err) {
      playSound('error'); // 🔊 Son d'échec
      const backendError = err.response?.data?.error || "Identification échouée";
      setError(backendError);
      setResult(null);
      logger.error("Recognition error", backendError);
    } finally {
      setLoading(false);
    }
  }, [webcamRef, soundEnabled]);

  // Auto-scan logic
  useEffect(() => {
    let interval;
    if (autoMode) {
      interval = setInterval(() => { if (!loading) handleCapture(); }, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div className="flex flex-col items-center p-6 space-y-6 bg-slate-50 min-h-screen font-sans">
      <header className="text-center space-y-2">
        <h1 className="text-3xl font-black text-slate-800 flex items-center justify-center gap-3">
          <UserCheck size={36} className="text-blue-600" /> 
          CHECK-IN FACIAL
        </h1>
        <div className="flex justify-center gap-4">
          <button 
            onClick={() => setSoundEnabled(!soundEnabled)}
            className="text-slate-400 hover:text-blue-500 transition-colors"
            aria-label={soundEnabled ? "Désactiver le son" : "Activer le son"}
          >
            {soundEnabled ? <Volume2 size={20} /> : <VolumeX size={20} />}
          </button>
        </div>
      </header>

      <main className="relative w-full max-w-2xl flex flex-col items-center">
        {/* Webcam Container */}
        <div className="relative overflow-hidden rounded-[2rem] border-[12px] border-white shadow-2xl bg-slate-900 aspect-video w-full">
          <Webcam
            audio={false}
            ref={webcamRef}
            screenshotFormat="image/jpeg"
            videoConstraints={videoConstraints}
            className="w-full h-full object-cover"
          />
          {loading && (
            <div className="absolute inset-0 flex items-center justify-center bg-blue-600/20 backdrop-blur-md">
              <RefreshCw className="text-white animate-spin" size={64} />
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex gap-4 mt-8 w-full max-w-md">
          <button
            onClick={handleCapture}
            disabled={loading}
            aria-label="Scanner mon visage pour pointer"
            className={`flex-1 py-4 rounded-2xl font-black text-white transition-all transform active:scale-95 flex items-center justify-center gap-3 shadow-xl ${
              loading ? 'bg-slate-300' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'
            }`}
          >
            <Fingerprint size={24} />
            {loading ? 'ANALYSE...' : 'POINTER'}
          </button>

          <button
            onClick={() => setAutoMode(!autoMode)}
            aria-pressed={autoMode}
            aria-label="Activer le scan automatique"
            className={`px-6 py-4 rounded-2xl font-bold border-2 transition-all ${
              autoMode 
                ? 'bg-green-600 border-green-600 text-white shadow-lg shadow-green-100' 
                : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'
            }`}
          >
            {autoMode ? 'AUTO ON' : 'AUTO OFF'}
          </button>
        </div>
      </main>

      {/* Results Display */}
      <footer className="w-full max-w-xl transition-all">
        {result && (
          <div role="alert" className="bg-white border-b-4 border-green-500 p-6 rounded-3xl shadow-xl flex items-start gap-6 animate-in zoom-in-95 duration-300">
            <div className="bg-green-100 p-4 rounded-2xl">
              <CheckCircle className="text-green-600" size={32} />
            </div>
            <div className="space-y-1">
              <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">{result.name}</h2>
              <p className="text-slate-500 font-medium">{result.email}</p>
              <p className="text-xs text-blue-500 font-bold pt-2">ID POINTAGE: #{result.attendanceId}</p>
            </div>
          </div>
        )}

        {error && (
          <div role="alert" className="bg-red-600 p-6 rounded-3xl shadow-xl flex items-center gap-4 animate-in slide-in-from-top-4">
            <XCircle className="text-white shrink-0" size={32} />
            <div className="text-white">
              <p className="font-black text-lg">ÉCHEC</p>
              <p className="text-red-100 text-sm opacity-90">{error}</p>
            </div>
          </div>
        )}
      </footer>
    </div>
  );
};

export default CameraRecognition;
